                const trailer = try readChunkedLine(&raw, stream, &pos);
                if (trailer.len == 0) {
                    return body.toOwnedSlice();
                }
                return error.UnsupportedTrailer;
            }
        }

        if (body.items.len + chunk_size > MAX_BODY_SIZE) {
            return error.PayloadTooLarge;
        }

        try ensureChunkedAvailable(&raw, stream, pos, chunk_size + 2);
        try body.appendSlice(raw.items[pos .. pos + chunk_size]);
        pos += chunk_size;

        if (!(raw.items[pos] == '\r' and raw.items[pos + 1] == '\n')) {
            return error.BadChunk;
        }
        pos += 2;
    }
}

fn routeRequest(
    allocator: mem.Allocator,
    stream: net.Stream,
    method: []const u8,
    path: []const u8,
    body: []const u8,
    head_only: bool,
) !void {
    if (mem.eql(u8, path, "/")) {
        if (mem.eql(u8, method, "GET") or head_only) {
            try serveFile(allocator, stream, "index.html", "text/html; charset=utf-8", "no-cache", head_only);
        } else if (mem.eql(u8, method, "OPTIONS")) {
            try sendOptions(stream);
        } else {
            try sendErrorWithMethod(stream, 405, head_only);
        }
    } else if (mem.eql(u8, path, "/api/chat")) {
        if (mem.eql(u8, method, "POST")) {
            try handleChat(allocator, stream, body);
        } else if (mem.eql(u8, method, "OPTIONS")) {
            try sendOptions(stream);
        } else {
            try sendErrorWithMethod(stream, 405, head_only);
        }
    } else if (mem.eql(u8, path, "/sw.js")) {
        if (mem.eql(u8, method, "GET") or head_only) {
            try serveFile(allocator, stream, "sw.js", "application/javascript", "public, max-age=3600", head_only);
        } else if (mem.eql(u8, method, "OPTIONS")) {
            try sendOptions(stream);
        } else {
            try sendErrorWithMethod(stream, 405, head_only);
        }
    } else if (mem.eql(u8, path, "/health")) {
        if (mem.eql(u8, method, "GET") or head_only) {
            try sendHealth(stream, head_only);
        } else if (mem.eql(u8, method, "OPTIONS")) {
            try sendOptions(stream);
        } else {
            try sendErrorWithMethod(stream, 405, head_only);
        }
    } else if (mem.eql(u8, method, "OPTIONS")) {
        try sendOptions(stream);
    } else if (mem.eql(u8, method, "GET") or head_only) {
        if (!try tryServeStaticFile(allocator, stream, path, head_only)) {
            try sendErrorWithMethod(stream, 404, head_only);
        }
    } else {
        try sendErrorWithMethod(stream, 404, head_only);
    }
}

fn isSafeStaticPath(path: []const u8) bool {
    if (path.len < 2) return false;
    if (path[0] != '/') return false;
    if (mem.indexOf(u8, path, "..") != null) return false;
    if (mem.indexOfScalar(u8, path, '\\') != null) return false;
    return true;
}

fn contentTypeForPath(path: []const u8) []const u8 {
    if (mem.endsWith(u8, path, ".html")) return "text/html; charset=utf-8";
    if (mem.endsWith(u8, path, ".js")) return "application/javascript";
    if (mem.endsWith(u8, path, ".css")) return "text/css; charset=utf-8";
    if (mem.endsWith(u8, path, ".json")) return "application/json";
    if (mem.endsWith(u8, path, ".svg")) return "image/svg+xml";
    if (mem.endsWith(u8, path, ".png")) return "image/png";
    if (mem.endsWith(u8, path, ".jpg") or mem.endsWith(u8, path, ".jpeg")) return "image/jpeg";
    if (mem.endsWith(u8, path, ".webp")) return "image/webp";
    if (mem.endsWith(u8, path, ".ico")) return "image/x-icon";
    if (mem.endsWith(u8, path, ".txt")) return "text/plain; charset=utf-8";
    return "application/octet-stream";
}

fn tryServeStaticFile(allocator: mem.Allocator, stream: net.Stream, path: []const u8, head_only: bool) !bool {
    if (!isSafeStaticPath(path)) {
        return false;
    }

    const rel = path[1..];
    if (rel.len == 0) {
        return false;
    }

    const file = fs.cwd().openFile(rel, .{}) catch |err| switch (err) {
        error.FileNotFound, error.BadPathName => return false,
        error.AccessDenied => {
            try sendErrorWithMethod(stream, 403, head_only);
            return true;
        },
        else => {
            try sendErrorWithMethod(stream, 500, head_only);
            return true;
        },
    };
    defer file.close();

    const stat = file.stat() catch {
        try sendErrorWithMethod(stream, 500, head_only);
        return true;
    };

    if (stat.kind != .file) {
        return false;
    }

    const size = @as(usize, @intCast(stat.size));
    if (size > MAX_BODY_SIZE) {
        try sendErrorWithMethod(stream, 413, head_only);
        return true;
    }

    const body = file.readToEndAlloc(allocator, size) catch {
        try sendErrorWithMethod(stream, 500, head_only);
        return true;
    };
    defer allocator.free(body);

    try sendResponse(stream, 200, "OK", contentTypeForPath(rel), "public, max-age=300", body, head_only);
    return true;
}

fn serveFile(
    allocator: mem.Allocator,
    stream: net.Stream,
    file_path: []const u8,
    content_type: []const u8,
    cache: []const u8,
    head_only: bool,
) !void {
    const file = fs.cwd().openFile(file_path, .{}) catch |err| switch (err) {
        error.FileNotFound, error.BadPathName => return sendErrorWithMethod(stream, 404, head_only),
        error.AccessDenied => return sendErrorWithMethod(stream, 403, head_only),
        else => return sendErrorWithMethod(stream, 500, head_only),
    };
    defer file.close();

    const stat = file.stat() catch return sendErrorWithMethod(stream, 500, head_only);
    const size = @as(usize, @intCast(stat.size));
    if (size > MAX_BODY_SIZE) {
        return sendErrorWithMethod(stream, 413, head_only);
    }

    const body = file.readToEndAlloc(allocator, size) catch return sendErrorWithMethod(stream, 500, head_only);
    defer allocator.free(body);

    try sendResponse(stream, 200, "OK", content_type, cache, body, head_only);
}

fn sendHealth(stream: net.Stream, head_only: bool) !void {
    var body_buf: [128]u8 = undefined;
    const body = try std.fmt.bufPrint(
        &body_buf,
        "{{\"status\":\"ok\",\"backend\":\"zig\",\"max_tokens\":{d}}}",
        .{MAX_TOKENS},
    );
    try sendJsonWithMethod(stream, 200, body, head_only);
}

fn handleChat(allocator: mem.Allocator, stream: net.Stream, body: []const u8) !void {
    const model_id = resolveModelId(allocator) catch |err| {
        const message = try std.fmt.allocPrint(allocator, "Configuration error: {}", .{err});
        defer allocator.free(message);
        try sendJsonErrorMessage(allocator, stream, 500, message, false);
        return;
    };
    defer allocator.free(model_id);

    const messages_json = extractMessages(allocator, body) catch |err| {
        const message = try std.fmt.allocPrint(allocator, "Invalid request: {}", .{err});
        defer allocator.free(message);
        try sendJsonErrorMessage(allocator, stream, 400, message, false);
        return;
    };
    defer allocator.free(messages_json);

    const outcome = try callAzureOpenAI(allocator, messages_json, model_id);
    defer allocator.free(outcome.text);

    switch (outcome.kind) {
        .success => {
            var resp_json = std.ArrayList(u8).init(allocator);
            defer resp_json.deinit();
            try json.stringify(
                .{ .response = outcome.text, .model = model_id, .backend = "azure" },
                .{},
                resp_json.writer(),
            );
            try sendJsonWithMethod(stream, 200, resp_json.items, false);
        },
        .bad_request => try sendJsonErrorMessage(allocator, stream, 400, outcome.text, false),
        .server_error => try sendJsonErrorMessage(allocator, stream, 500, outcome.text, false),
        .upstream_error => try sendJsonErrorMessage(allocator, stream, 502, outcome.text, false),
    }
}

fn resolveModelId(allocator: mem.Allocator) ![]u8 {
    return process.getEnvVarOwned(allocator, "AZURE_EXISTING_AGENT_ID") catch {
        return process.getEnvVarOwned(allocator, "AZURE_MODEL") catch try allocator.dupe(u8, DEFAULT_AGENT_ID);
    };
}

fn tryInkoAgent(allocator: mem.Allocator, input: []const u8) !?[]u8 {
    fs.cwd().access(INKO_AGENT_PATH, .{}) catch return error.AgentNotFound;

    var child = std.process.Child.init(&[_][]const u8{ INKO_AGENT_PATH }, allocator);
    child.stdin_behavior = .Pipe;
    child.stdout_behavior = .Pipe;
    child.stderr_behavior = .Inherit;

    try child.spawn();

    errdefer {
        _ = child.kill() catch {};
        _ = child.wait() catch {};
    }

    try child.stdin.?.writeAll(input);
    child.stdin.?.close();
    child.stdin = null;

    const stdout = try child.stdout.?.readToEndAlloc(allocator, MAX_BODY_SIZE);
    errdefer allocator.free(stdout);

    const term = try child.wait();
    switch (term) {
        .Exited => |code| {
            if (code != 0) {
                allocator.free(stdout);
                return error.AgentNonZeroExit;
            }
        },
        else => {
            allocator.free(stdout);
            return error.AgentCrashed;
        },
    }

    return stdout;
}

fn callAzureOpenAI(allocator: mem.Allocator, messages_json: []const u8, model_id: []const u8) !TextOutcome {
    const api_key = process.getEnvVarOwned(allocator, "AZURE_API_KEY") catch {
        return TextOutcome{ .kind = .server_error, .text = try allocator.dupe(u8, "AZURE_API_KEY is not configured.") };
    };
    defer allocator.free(api_key);

    const endpoint = process.getEnvVarOwned(allocator, "AZURE_EXISTING_AIPROJECT_ENDPOINT") catch
        try allocator.dupe(u8, DEFAULT_ENDPOINT);
    defer allocator.free(endpoint);

    const body_model = process.getEnvVarOwned(allocator, "AZURE_MODEL") catch
        try allocator.dupe(u8, "gpt-5.3-chat");
    defer allocator.free(body_model);

    return callResponses(allocator, endpoint, api_key, messages_json, model_id, body_model, MAX_TOKENS) catch |err| {
        return TextOutcome{ .kind = .upstream_error, .text = try std.fmt.allocPrint(allocator, "API request failed: {}", .{err}) };
    };
}

fn extractMessages(allocator: mem.Allocator, body: []const u8) ![]u8 {
    const parsed = try json.parseFromSlice(json.Value, allocator, body, .{});
    defer parsed.deinit();

    if (parsed.value != .object) return error.InvalidBody;
    const msgs = parsed.value.object.get("messages") orelse return error.MissingMessages;
    if (msgs != .array) return error.InvalidMessages;

    for (msgs.array.items) |item| {
        if (item != .object) return error.InvalidMessages;
        const role = item.object.get("role") orelse return error.InvalidMessages;
        const content = item.object.get("content") orelse return error.InvalidMessages;
        if (role != .string) return error.InvalidMessages;
        switch (content) {
            .string, .array, .object => {},
            else => return error.InvalidMessages,
        }
    }

    var out = std.ArrayList(u8).init(allocator);
    errdefer out.deinit();
    try json.stringify(msgs, .{}, out.writer());
    return out.toOwnedSlice();
}

fn callResponses(
    allocator: mem.Allocator,
    endpoint: []const u8,
    api_key: []const u8,
    messages_json: []const u8,
    model_id: []const u8,
    body_model: []const u8,
    max_tokens: u32,
) !TextOutcome {
    var http_client = http.Client{ .allocator = allocator };
    defer http_client.deinit();

    const norm = if (mem.endsWith(u8, endpoint, "/")) endpoint[0 .. endpoint.len - 1] else endpoint;

    const agent_name = if (mem.indexOfScalar(u8, model_id, ':')) |colon|
        model_id[0..colon]
    else
        model_id;

    const api_url = try std.fmt.allocPrint(
        allocator,
        "{s}/applications/{s}/protocols/openai/responses?api-version=2025-11-15-preview",
        .{ norm, agent_name },
    );
    defer allocator.free(api_url);

    const req_body = try buildResponsesBody(allocator, messages_json, body_model, max_tokens);
    defer allocator.free(req_body);

    std.log.info("POST {s}", .{api_url});

    const uri = try std.Uri.parse(api_url);

    var server_header_buffer: [16384]u8 = undefined;
    var req = try http_client.open(.POST, uri, .{
        .server_header_buffer = &server_header_buffer,
        .extra_headers = &.{
            .{ .name = "content-type", .value = "application/json" },
            .{ .name = "accept", .value = "application/json" },
            .{ .name = "api-key", .value = api_key },
        },
    });
    defer req.deinit();
    req.transfer_encoding = .{ .content_length = req_body.len };
    try req.send();
    try req.writeAll(req_body);
    try req.finish();
    try req.wait();

    const status_int = @intFromEnum(req.response.status);
    std.log.info("status={d}", .{status_int});

    var resp_body = std.ArrayList(u8).init(allocator);
    defer resp_body.deinit();
    try req.reader().readAllArrayList(&resp_body, MAX_BODY_SIZE);

    if (status_int < 200 or status_int >= 300) {
        return TextOutcome{ .kind = .upstream_error, .text = try extractErrorMessage(allocator, resp_body.items) };
    }

    return TextOutcome{ .kind = .success, .text = try extractOutputText(allocator, resp_body.items) };
}

fn buildResponsesBody(
    allocator: mem.Allocator,
    input_json: []const u8,
    model_id: []const u8,
    max_tokens: u32,
) ![]u8 {
    var out = std.ArrayList(u8).init(allocator);
    errdefer out.deinit();
    const w = out.writer();
    try w.writeAll("{\"model\":");
    try json.stringify(model_id, .{}, w);
    try w.writeAll(",\"input\":");
    try w.writeAll(input_json);
    try w.print(",\"max_output_tokens\":{d}}}", .{max_tokens});
    return out.toOwnedSlice();
}

fn appendJsonText(buffer: *std.ArrayList(u8), value: json.Value) !void {
    switch (value) {
        .string => |text| {
            if (text.len > 0) {
                try buffer.appendSlice(text);
            }
        },
        .array => |arr| {
            for (arr.items) |item| {
                try appendJsonText(buffer, item);
            }
        },
        .object => |obj| {
            if (obj.get("text")) |text_value| {
                try appendJsonText(buffer, text_value);
            }
            if (obj.get("value")) |value_value| {
                try appendJsonText(buffer, value_value);
            }
            if (obj.get("content")) |content_value| {
                try appendJsonText(buffer, content_value);
            }
        },
        else => {},
    }
}

fn extractOutputText(allocator: mem.Allocator, body: []const u8) ![]u8 {
    const parsed = json.parseFromSlice(json.Value, allocator, body, .{}) catch {
        return try allocator.dupe(u8, "Failed to parse API response.");
    };
    defer parsed.deinit();

    if (parsed.value != .object) {
        return try allocator.dupe(u8, "The API response is not a JSON object.");
    }

    var buffer = std.ArrayList(u8).init(allocator);
    errdefer buffer.deinit();

    if (parsed.value.object.get("output_text")) |output_text| {
        try appendJsonText(&buffer, output_text);
    }

    if (buffer.items.len == 0) {
        if (parsed.value.object.get("output")) |output| {
            try appendJsonText(&buffer, output);
        }
    }

    if (buffer.items.len > 0) {
        return buffer.toOwnedSlice();
    }

    if (parsed.value.object.get("error")) |err_value| {
        var msg = std.ArrayList(u8).init(allocator);
        defer msg.deinit();
        try json.stringify(err_value, .{}, msg.writer());
        return try std.fmt.allocPrint(allocator, "API Error: {s}", .{msg.items});
    }

    return try allocator.dupe(u8, "Could not extract response from API.");
}

fn extractErrorMessage(allocator: mem.Allocator, body: []const u8) ![]u8 {
    const parsed = json.parseFromSlice(json.Value, allocator, body, .{}) catch {
        return try allocator.dupe(u8, body);
    };
    defer parsed.deinit();

    if (parsed.value == .object) {
        if (parsed.value.object.get("error_description")) |value| {
            if (value == .string and value.string.len > 0) {
                return try allocator.dupe(u8, value.string);
            }
        }
        if (parsed.value.object.get("message")) |value| {
            if (value == .string and value.string.len > 0) {
                return try allocator.dupe(u8, value.string);
            }
        }
        if (parsed.value.object.get("error")) |err_value| {
            if (err_value == .object) {
                if (err_value.object.get("message")) |message_value| {
                    if (message_value == .string and message_value.string.len > 0) {
                        return try allocator.dupe(u8, message_value.string);
                    }
                }
            }
            if (err_value == .string and err_value.string.len > 0) {
                return try allocator.dupe(u8, err_value.string);
            }
        }
    }

    return try allocator.dupe(u8, body);
}

fn statusText(status: u16) []const u8 {
    return switch (status) {
        200 => "OK",
        201 => "Created",
        204 => "No Content",
        400 => "Bad Request",
        403 => "Forbidden",
        404 => "Not Found",
        405 => "Method Not Allowed",
        411 => "Length Required",
        413 => "Payload Too Large",
        429 => "Too Many Requests",
        431 => "Request Header Fields Too Large",
        500 => "Internal Server Error",
        501 => "Not Implemented",
        502 => "Bad Gateway",
        else => "Error",
    };
}

fn writeCommonHeaders(stream: net.Stream, status: u16, content_type: []const u8, content_length: usize, cache: []const u8) !void {
    var hdr: [1024]u8 = undefined;
    const hdr_str = try std.fmt.bufPrint(
        &hdr,
        "HTTP/1.1 {d} {s}\r\nContent-Type: {s}\r\nContent-Length: {d}\r\nCache-Control: {s}\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, POST, HEAD, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type\r\nConnection: close\r\n\r\n",
        .{ status, statusText(status), content_type, content_length, cache },
    );
    try stream.writeAll(hdr_str);
}

fn sendResponse(
    stream: net.Stream,
    status: u16,
    status_text: []const u8,
    content_type: []const u8,
    cache: []const u8,
    body: []const u8,
    head_only: bool,
) !void {
    _ = status_text;
    try writeCommonHeaders(stream, status, content_type, body.len, cache);
    if (!head_only and body.len > 0) {
        try stream.writeAll(body);
    }
}

fn sendJsonWithMethod(stream: net.Stream, status: u16, body: []const u8, head_only: bool) !void {
    try sendResponse(stream, status, statusText(status), "application/json", "no-cache", body, head_only);
}

fn sendJson(stream: net.Stream, status: u16, body: []const u8) !void {
    try sendJsonWithMethod(stream, status, body, false);
}

fn sendJsonErrorMessage(allocator: mem.Allocator, stream: net.Stream, status: u16, message: []const u8, head_only: bool) !void {
    var out = std.ArrayList(u8).init(allocator);
    defer out.deinit();
    try json.stringify(.{ .@"error" = message }, .{}, out.writer());
    try sendJsonWithMethod(stream, status, out.items, head_only);
}

fn sendError(stream: net.Stream, status: u16) !void {
    try sendErrorWithMethod(stream, status, false);
}

fn sendErrorWithMethod(stream: net.Stream, status: u16, head_only: bool) !void {
    const body: []const u8 = switch (status) {
        400 => "{\"error\":\"Bad Request\"}",
        403 => "{\"error\":\"Forbidden\"}",
        404 => "{\"error\":\"Not Found\"}",
        405 => "{\"error\":\"Method Not Allowed\"}",
        411 => "{\"error\":\"Length Required\"}",
        413 => "{\"error\":\"Payload Too Large\"}",
        429 => "{\"error\":\"Too Many Requests\"}",
        431 => "{\"error\":\"Request Header Fields Too Large\"}",
        500 => "{\"error\":\"Internal Server Error\"}",
        501 => "{\"error\":\"Not Implemented\"}",
        502 => "{\"error\":\"Bad Gateway\"}",
        else => "{\"error\":\"Error\"}",
    };
    try sendJsonWithMethod(stream, status, body, head_only);
}

fn sendOptions(stream: net.Stream) !void {
    try stream.writeAll(
        "HTTP/1.1 204 No Content\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, POST, HEAD, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type\r\nContent-Length: 0\r\nCache-Control: no-cache\r\nConnection: close\r\n\r\n",
    );
}


