fn required_env(name: String) -> Result[String, String] {
  match env.get(name) {
    case Ok(value) -> {
      let trimmed = value.trim

      if trimmed.size > 0 {
        Result.Ok(trimmed)
      } else {
        Result.Error('The environment variable ${name} is empty')
      }
    }
    case Error(_) -> Result.Error('The environment variable ${name} is missing')
  }
}

fn optional_env(name: String, fallback: String) -> String {
  match env.get(name) {
    case Ok(value) -> {
      let trimmed = value.trim

      if trimmed.size > 0 {
        trimmed
      } else {
        fallback
      }
    }
    case _ -> fallback
  }
}

fn strip_trailing_slashes(value: String) -> String {
  let mut current = value

  if current == '/' {
    return current
  }

  loop {
    match current.strip_suffix('/') {
      case Some(val) -> {
        if val.size > 0 {
          current = val
        } else {
          return current
        }
      }
      case None -> return current
    }
  }
}

